    if (text == "underline") {
        value = MessageEntity::Type::Underline;
        return;
    }
    if (text == "strikethrough") {
        value = MessageEntity::Type::Strikethrough;
        return;
    }
    if (text == "spoiler") {
        value = MessageEntity::Type::Spoiler;
        return;
    }
    if (text == "blockquote") {
        value = MessageEntity::Type::Blockquote;
        return;
    }
    if (text == "expandable_blockquote") {
        value = MessageEntity::Type::ExpandableBlockquote;
        return;
    }
    if (text == "code") {
        value = MessageEntity::Type::Code;
        return;
    }
    if (text == "pre") {
        value = MessageEntity::Type::Pre;
        return;
    }
    if (text == "text_link") {
        value = MessageEntity::Type::TextLink;
        return;
    }
    if (text == "text_mention") {
        value = MessageEntity::Type::TextMention;
        return;
    }
    if (text == "custom_emoji") {
        value = MessageEntity::Type::CustomEmoji;
        return;
    }
    if (text == "date_time") {
        value = MessageEntity::Type::DateTime;
        return;
    }
    throw std::invalid_argument("Unknown MessageEntity.Type value: " + text);
